/**
 * Spoločná ICE konfigurácia pre WebRTC peer spojenia.
 *
 * Okrem verejných STUN serverov pridávame aj verejne dostupné TURN servery
 * (OpenRelay od metered.ca). TURN je nutný pre spojenia medzi zariadeniami
 * v rôznych sieťach (napr. mobil na 4G ↔ notebook za firewallom), kde
 * priame UDP pripojenie cez STUN nestačí. Bez TURN-u sa typicky stane,
 * že signalizácia prejde, ale médiá netečú a používateľ vidí čiernu
 * obrazovku alebo nepočuje zvuk.
 */
export const RTC_PEER_CONFIG = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun.cloudflare.com:3478' },
    {
      urls: 'turn:openrelay.metered.ca:80',
      username: 'openrelayproject',
      credential: 'openrelayproject'
    },
    {
      urls: 'turn:openrelay.metered.ca:443',
      username: 'openrelayproject',
      credential: 'openrelayproject'
    },
    {
      urls: 'turn:openrelay.metered.ca:443?transport=tcp',
      username: 'openrelayproject',
      credential: 'openrelayproject'
    }
  ],
  iceCandidatePoolSize: 10,
  bundlePolicy: 'max-bundle',
  rtcpMuxPolicy: 'require'
};

/**
 * Detekcia pomalého pripojenia – ak browser exposne Network Information API,
 * vieme z neho odhadnúť kvalitu siete a podľa toho znížiť rozlíšenie
 * a bitrate. To pomáha hlavne na slabých Wi-Fi/4G, kde inak WebRTC
 * skúša poslať plné HD a pakety sa stratia (čierne video, žiadny zvuk).
 */
export function getNetworkProfile() {
  if (typeof navigator === 'undefined') return 'unknown';
  const c = navigator.connection || navigator.webkitConnection || navigator.mozConnection;
  if (!c) return 'unknown';
  if (c.saveData) return 'slow';
  const effective = c.effectiveType || '';
  if (effective === 'slow-2g' || effective === '2g') return 'slow';
  if (effective === '3g') return 'medium';
  // Aj keď máme „4g", downlink môže byť veľmi nízky (slabá Wi-Fi):
  // pri pod 1.5 Mbps to považujeme za pomalé.
  if (typeof c.downlink === 'number' && c.downlink > 0 && c.downlink < 1.5) return 'medium';
  return 'fast';
}

/**
 * Postupne skúšame menej náročné video constraints, aby sme zvládli
 * staršie/slabšie zariadenia (napr. starý Asus, mobil) bez pádu.
 * Pre slabé pripojenia začíname rovno na nižšom rozlíšení – inak browser
 * negotiuje plné HD a pri následnom downscalingu sa video načas „zasekne“.
 */
const VIDEO_CONSTRAINTS_FAST = [
  {
    audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
    video: {
      facingMode: 'user',
      width: { ideal: 854, max: 1280 },
      height: { ideal: 480, max: 720 },
      frameRate: { ideal: 24, max: 30 }
    }
  },
  {
    audio: true,
    video: {
      facingMode: 'user',
      width: { ideal: 640, max: 854 },
      height: { ideal: 360, max: 480 },
      frameRate: { ideal: 20, max: 24 }
    }
  },
  { audio: true, video: { facingMode: 'user' } },
  { audio: true, video: true }
];

const VIDEO_CONSTRAINTS_MEDIUM = [
  {
    audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
    video: {
      facingMode: 'user',
      width: { ideal: 640, max: 854 },
      height: { ideal: 360, max: 480 },
      frameRate: { ideal: 18, max: 24 }
    }
  },
  {
    audio: true,
    video: {
      facingMode: 'user',
      width: { ideal: 480, max: 640 },
      height: { ideal: 270, max: 360 },
      frameRate: { ideal: 15, max: 20 }
    }
  },
  { audio: true, video: { facingMode: 'user' } },
  { audio: true, video: true }
];

const VIDEO_CONSTRAINTS_SLOW = [
  {
    audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
    video: {
      facingMode: 'user',
      width: { ideal: 320, max: 480 },
      height: { ideal: 240, max: 360 },
      frameRate: { ideal: 12, max: 15 }
    }
  },
  { audio: true, video: { facingMode: 'user', frameRate: { max: 12 } } },
  { audio: true, video: true }
];

function getVideoConstraintsTry(networkProfile = getNetworkProfile()) {
  if (networkProfile === 'slow') return VIDEO_CONSTRAINTS_SLOW;
  if (networkProfile === 'medium') return VIDEO_CONSTRAINTS_MEDIUM;
  return VIDEO_CONSTRAINTS_FAST;
}

export async function getUserMediaWithFallbackOptions(options = {}) {
  const {
    audio = true,
    video = true,
    allowEmpty = false
  } = options;

  if (!audio && !video) {
    return new MediaStream();
  }

  if (!navigator.mediaDevices?.getUserMedia) {
    if (allowEmpty) return new MediaStream();
    throw new Error('Tento prehliadač nepodporuje prístup ku kamere/mikrofónu.');
  }

  const networkProfile = getNetworkProfile();
  const tryConstraints = [];
  if (audio && video) {
    tryConstraints.push(...getVideoConstraintsTry(networkProfile));
  } else if (video) {
    if (networkProfile === 'slow') {
      tryConstraints.push(
        {
          video: {
            facingMode: 'user',
            width: { ideal: 320, max: 480 },
            height: { ideal: 240, max: 360 },
            frameRate: { ideal: 12, max: 15 }
          }
        },
        { video: { facingMode: 'user' } },
        { video: true }
      );
    } else {
      tryConstraints.push(
        {
          video: {
            facingMode: 'user',
            width: { ideal: 854, max: 1280 },
            height: { ideal: 480, max: 720 },
            frameRate: { ideal: 24, max: 30 }
          }
        },
        { video: { facingMode: 'user' } },
        { video: true }
      );
    }
  } else if (audio) {
    tryConstraints.push(
      { audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } },
      { audio: true }
    );
  }

  let lastError = null;
  for (const constraints of tryConstraints) {
    try {
      return await navigator.mediaDevices.getUserMedia(constraints);
    } catch (err) {
      lastError = err;
    }
  }

  // Posledná záchrana: skús získať audio a video samostatne a spoj ich do jedného streamu.
  if (audio && video) {
    const tracks = [];
    try {
      const audioOnly = await navigator.mediaDevices.getUserMedia({ audio: true });
      tracks.push(...audioOnly.getTracks());
    } catch (err) {
      if (!lastError) lastError = err;
    }
    try {
      const videoOnly = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      tracks.push(...videoOnly.getTracks());
    } catch (err) {
      if (!lastError) lastError = err;
    }
    if (tracks.length > 0) {
      return new MediaStream(tracks);
    }
  }

  if (allowEmpty) {
    return new MediaStream();
  }

  if (lastError) throw lastError;
  throw new Error('Nepodarilo sa získať médiá zo zariadenia.');
}

/**
 * Spoľahlivé pripojenie streamu k <video>/<audio> elementu.
 * iOS Safari niekedy potrebuje druhý play() v ďalšom animation frame,
 * preto sa volá viackrát. Ak je `srcObject` rovnaký, neresetujeme ho –
 * ináč by Safari preblikol čiernym snímkom pri každom rerenderi.
 */
export function attachStreamToVideo(videoEl, stream) {
  if (!videoEl || !stream) return;
  if (videoEl.srcObject !== stream) {
    videoEl.srcObject = stream;
  }
  const safePlay = () => {
    const promise = videoEl.play?.();
    if (promise && typeof promise.catch === 'function') {
      promise.catch(() => {});
    }
  };
  safePlay();
  if (typeof requestAnimationFrame === 'function') {
    requestAnimationFrame(safePlay);
  }
}

/**
 * Detekcia, či má daný stream aspoň jednu živú video stopu.
 */
export function streamHasLiveVideo(stream) {
  if (!stream) return false;
  return stream
    .getVideoTracks()
    .some((track) => track.readyState === 'live' && !track.muted);
}

/**
 * Profil parametrov enkódera pre rôzne typy obsahu. WebRTC encoder by sa bez
 * obmedzenia snažil využiť maximum dostupnej linky a pri pomalej wifi/4G
 * tým spôsobí veľký delay (paket-buffering). Ručné nastavenie maxBitrate
 * + degradationPreference výrazne zlepšuje stabilitu na slabších linkách.
 *
 * Hodnoty sú zámerne konzervatívne (nižšie ako predtým), aby sa video
 * vôbec preklepalo cez slabé Wi-Fi. Adaptívny monitor (monitorPeerBandwidth)
 * ich pri detekcii vysokých strát ešte zníži, takže pripojenie ostane
 * funkčné aj v zhoršujúcich sa podmienkach.
 */
const ENCODER_PROFILES = {
  fast: {
    camera: {
      maxBitrate: 600_000,
      maxFramerate: 24,
      priority: 'medium',
      networkPriority: 'medium',
      degradationPreference: 'maintain-framerate'
    },
    screen: {
      maxBitrate: 1_200_000,
      maxFramerate: 15,
      priority: 'high',
      networkPriority: 'high',
      degradationPreference: 'maintain-resolution'
    },
    audio: {
      priority: 'high',
      networkPriority: 'high'
    }
  },
  medium: {
    camera: {
      maxBitrate: 350_000,
      maxFramerate: 18,
      priority: 'medium',
      networkPriority: 'medium',
      degradationPreference: 'maintain-framerate'
    },
    screen: {
      maxBitrate: 700_000,
      maxFramerate: 12,
      priority: 'high',
      networkPriority: 'high',
      degradationPreference: 'maintain-resolution'
    },
    audio: {
      priority: 'high',
      networkPriority: 'high'
    }
  },
  slow: {
    camera: {
      maxBitrate: 180_000,
      maxFramerate: 12,
      priority: 'low',
      networkPriority: 'low',
      degradationPreference: 'maintain-framerate'
    },
    screen: {
      maxBitrate: 400_000,
      maxFramerate: 8,
      priority: 'high',
      networkPriority: 'medium',
      degradationPreference: 'maintain-resolution'
    },
    audio: {
      priority: 'high',
      networkPriority: 'high'
    }
  }
};

function pickProfile(kind, networkProfile = getNetworkProfile()) {
  const map = ENCODER_PROFILES[networkProfile] || ENCODER_PROFILES.fast;
  return map[kind] || null;
}

/**
 * Aplikuje encoding parametre na RTCRtpSender. Bez toho WebRTC žerie všetku
 * dostupnú šírku pásma a pri kolísavom pripojení vznikajú obrovské delays.
 * Použiť po každom replaceTrack alebo setLocalDescription.
 */
export async function applyEncodingParameters(sender, kind, networkProfile = getNetworkProfile()) {
  if (!sender) return;
  const profile = pickProfile(kind, networkProfile);
  if (!profile) return;
  try {
    const params = sender.getParameters() || {};
    if (!params.encodings || params.encodings.length === 0) {
      params.encodings = [{}];
    }
    params.encodings = params.encodings.map((enc) => {
      const next = { ...enc };
      if (profile.maxBitrate !== undefined) next.maxBitrate = profile.maxBitrate;
      if (profile.maxFramerate !== undefined) next.maxFramerate = profile.maxFramerate;
      if (profile.priority !== undefined) next.priority = profile.priority;
      if (profile.networkPriority !== undefined) next.networkPriority = profile.networkPriority;
      return next;
    });
    if (profile.degradationPreference !== undefined) {
      params.degradationPreference = profile.degradationPreference;
    }
    await sender.setParameters(params);
  } catch (error) {
    // Niektoré prehliadače (Safari starších verzií) nepodporujú všetky polia.
    // Failure tu nie je kritická – stratíme len optimalizáciu.
    console.warn(`[encoder] setParameters(${kind}) zlyhal:`, error?.message || error);
  }
}

/**
 * Pravidelne číta WebRTC štatistiky a reaktívne znižuje bitrate, ak detekuje
 * stratenosť paketov alebo veľký roundTripTime. Tým predídeme „čiernej
 * obrazovke" pri zhoršujúcom sa Wi-Fi – radšej posielame menej, ale stabilne.
 *
 * Vracia funkciu na zastavenie monitora (zavolaj pri close peer connection).
 */
export function monitorPeerBandwidth(peerConnection) {
  if (!peerConnection || typeof peerConnection.getStats !== 'function') return () => {};

  const lastStats = new Map(); // ssrc -> { packetsLost, packetsSent, ts }
  let degradedSteps = 0;
  let lastApplyTs = 0;

  const tick = async () => {
    if (peerConnection.connectionState === 'closed') return;
    let stats;
    try {
      stats = await peerConnection.getStats();
    } catch (e) {
      return;
    }

    const issues = [];

    stats.forEach((report) => {
      if (report.type === 'outbound-rtp' && report.kind === 'video' && !report.isRemote) {
        const ssrc = report.ssrc;
        const packetsSent = Number(report.packetsSent || 0);
        const packetsLost = Number(report.packetsLost || 0);
        const prev = lastStats.get(ssrc);
        if (prev) {
          const dSent = packetsSent - prev.packetsSent;
          const dLost = packetsLost - prev.packetsLost;
          if (dSent > 30) {
            const lossRatio = dLost / Math.max(1, dSent + dLost);
            if (lossRatio > 0.1) issues.push({ kind: 'loss', value: lossRatio });
          }
        }
        lastStats.set(ssrc, { packetsSent, packetsLost, ts: Date.now() });
      }
      if (report.type === 'candidate-pair' && report.state === 'succeeded' && report.nominated) {
        const rtt = Number(report.currentRoundTripTime || 0);
        if (rtt > 0.6) issues.push({ kind: 'rtt', value: rtt });
      }
    });

    const now = Date.now();
    if (issues.length > 0 && now - lastApplyTs > 8000 && degradedSteps < 3) {
      degradedSteps += 1;
      lastApplyTs = now;
      const factor = 1 - 0.3 * degradedSteps; // 0.7, 0.4, 0.1
      try {
        const senders = peerConnection.getSenders();
        for (const sender of senders) {
          const kind = sender.track?.kind;
          if (!kind) continue;
          const params = sender.getParameters() || {};
          if (!params.encodings || params.encodings.length === 0) {
            params.encodings = [{}];
          }
          params.encodings = params.encodings.map((enc) => ({
            ...enc,
            maxBitrate: Math.max(80_000, Math.floor((enc.maxBitrate || 600_000) * factor))
          }));
          try {
            await sender.setParameters(params);
          } catch (e) {
            /* ignore */
          }
        }
        console.info(`[bw-monitor] zhoršené pripojenie, znížený bitrate na ${Math.round(factor * 100)}% (krok ${degradedSteps})`);
      } catch (e) {
        /* ignore */
      }
    }
  };

  const intervalId = setInterval(tick, 5000);
  return () => clearInterval(intervalId);
}
